"use client";
import {useEffect,useRef,useState} from "react";
import {learningQuestionTopics as topics} from "@/lib/learning-question-topics";
import {ArrowUp,ArrowUpRight,Loader2,Square,Plus,BookOpen} from "lucide-react";
import type {KnowledgeAnswer,KnowledgeTurn} from "@/lib/knowledge-answer";
type Exchange={id:number;question:string;answer:KnowledgeAnswer};
export function KnowledgeChat({initialQuestion=""}:{initialQuestion?:string}){
 const [draft,setDraft]=useState(initialQuestion),[exchanges,setExchanges]=useState<Exchange[]>([]),[pending,setPending]=useState(""),[error,setError]=useState("");
 const [topic,setTopic]=useState("骗局识别");
 const controller=useRef<AbortController|null>(null),epoch=useRef(0),last=useRef<HTMLDivElement>(null);
 const [prefill,setPrefill]=useState(initialQuestion);
 if(prefill!==initialQuestion){setPrefill(initialQuestion);if(initialQuestion)setDraft(initialQuestion);}
 useEffect(()=>()=>{epoch.current++;controller.current?.abort();},[]);
 useEffect(()=>{if(exchanges.length)last.current?.scrollIntoView({behavior:"smooth",block:"nearest"});},[exchanges.length]);
 async function ask(question=draft){
  if(pending||!question.trim())return;const q=question.trim();setDraft("");setPending(q);setError("");const token=++epoch.current,ctl=new AbortController();controller.current=ctl;
  const history:KnowledgeTurn[]=exchanges.slice(-3).flatMap(e=>[{role:"user" as const,content:e.question},{role:"assistant" as const,content:e.answer.points.map(p=>p.text).join("\n").slice(0,2400)||e.answer.message||"资料不足"}]);
  try{const r=await fetch("/api/knowledge",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({question:q,history}),signal:AbortSignal.any([ctl.signal,AbortSignal.timeout(26000)])});const data=await r.json() as KnowledgeAnswer&{error?:string};if(!r.ok)throw Error(data.error||"答疑暂未完成");if(token===epoch.current)setExchanges(v=>[...v.slice(-19),{id:token,question:q,answer:data}]);}
  catch(e){if(token===epoch.current){setDraft(q);setError(e instanceof Error&&e.name==="TimeoutError"?"等待超时，问题已保留，请重试。":"答疑暂未完成，问题已保留，请重试。");}}
  finally{if(token===epoch.current)setPending("");}
 }
 function resetConversation(){setExchanges([]);setError("");setDraft("");}
 function stop(){epoch.current++;controller.current?.abort();setDraft(pending);setPending("");setError("已停止，问题已放回输入框。");}
 return <section className={"knowledge-v2 "+(exchanges.length||pending?"has-thread":"")} aria-label="反诈知识答疑"><aside className="knowledge-history"><h2>问答记录</h2><button disabled={Boolean(pending)} onClick={resetConversation}><Plus size={16}/>新的问题</button><small>本次提问</small>{exchanges.length?exchanges.map(e=><button key={e.id} onClick={()=>document.getElementById("exchange-"+e.id)?.scrollIntoView({behavior:"smooth"})}>{e.question}</button>):<p>还没有提问。<br/>从你关心的问题开始。</p>}{exchanges.length>0&&<button disabled={Boolean(pending)} onClick={()=>setExchanges([])}>清空本次记录</button>}</aside><div className="knowledge-main"><div className="knowledge-mobile-tools"><span>反诈知识答疑</span><button disabled={Boolean(pending)} onClick={resetConversation}><Plus size={15}/>新的问题</button></div>{!exchanges.length&&!pending&&<header className="knowledge-welcome"><img src="/design/question-desk.webp" alt="笔记本、钢笔与手机"/><div><h1>知识问答</h1><p>解释概念、核实方法与常见误区。</p></div></header>} <div className="learn-thread" aria-live="polite">{exchanges.map(e=><article className="learn-exchange" id={"exchange-"+e.id} key={e.id}><h3>{e.question}</h3><div className="learn-response"><span className="learn-answer-label">{e.answer.engine==="model"?"知识讲解":e.answer.engine==="retrieval"?"已收录知识要点":"资料边界"}</span>{e.answer.message&&<p>{e.answer.message}</p>}{e.answer.warning&&<p className="learn-status">{e.answer.warning}</p>}{e.answer.points.map((p,i)=><p key={i}>{p.text}</p>)}{e.answer.sources.length>0&&<details className="learn-sources"><summary>查看本次依据 · {e.answer.sources.length}条</summary>{e.answer.sources.map(s=><div key={s.id}><a href={s.source.url} target="_blank" rel="noreferrer">{s.source.title}<ArrowUpRight size={12}/></a><small>{s.source.publisher} · {s.source.date} · {s.source.locator}</small>{s.source.scope&&<small>{s.source.scope}</small>}</div>)}</details>}</div></article>)}{pending&&<div className="learn-pending" role="status"><strong>{pending}</strong><span><Loader2 className="spin" size={15}/>正在查找依据并整理讲解…</span><button onClick={stop}><Square size={13}/>停止</button></div>}<div ref={last}/></div>
 {exchanges.length>0&&!pending&&<div className="learn-followups">{["再简单讲一下","举个大学生的例子","把核实步骤讲清楚"].map(q=><button key={q} onClick={()=>void ask(q)}>{q}</button>)}</div>}
 <form onSubmit={e=>{e.preventDefault();void ask();}}><label className="sr-only" htmlFor="theory-question">你的问题</label><div className="learn-compose"><textarea id="theory-question" rows={2} maxLength={300} value={draft} disabled={Boolean(pending)} onChange={e=>setDraft(e.target.value)} placeholder="想了解什么？直接写下你的问题…" required/><button disabled={Boolean(pending)||!draft.trim()} aria-label="发送问题"><span>发送问题</span><ArrowUp size={18}/></button></div><small>请勿填写姓名、账号等个人信息。</small></form>{!exchanges.length&&!pending&&<section className="knowledge-discover"><h2>也可以从这些问题开始</h2><nav aria-label="问题主题">{Object.keys(topics).map(t=><button key={t} aria-pressed={topic===t} onClick={()=>setTopic(t)}>{t}</button>)}</nav><div>{topics[topic].map((q,i)=><button key={q} onClick={()=>void ask(q)}><span>0{i+1}</span>{q}<ArrowUpRight size={16}/></button>)}</div><p><BookOpen size={16}/>回答附资料依据；拿不准的信息会说明。</p></section>}{error&&<p className="learn-status" role="alert">{error}</p>}
 </div></section>;
}

"use client";

import {useRef,useState} from "react";
import {ArrowLeft, ArrowRight, ArrowUpRight, Search, BookOpen, Play, Check} from "lucide-react";
import {lessons, type LearningProgress, type Lesson} from "@/lib/learning";
import {newsCases} from "@/lib/case-library";
import {videoCourses} from "@/lib/video-courses";
import {lessonArtwork,lessonEditorial} from "@/lib/lesson-editorial";

export const subjects = ["求职兼职", "刷单返利", "二手交易", "冒充客服", "交友与AI伪造", "购票骗局"];
const formats = ["全部", "真人讲解", "动画教学", "图文课程"];
// Mix formats and subjects in the opening rows; filters still expose the complete catalogue.
const featured = [
  "human-job", "animation-bird", "human-share",
  "trade-platform", "identity", "ticket-channel", "animation-pig",
  "animation-cards", "human-rebate", "identity",
  "human-face", "animation-campus", "job-fee", "human-pay", "animation-wind",
];
const illustratedFeatured=["jobs","rewards","trade-link","service-share","identity","ticket-channel"];
type VideoCourse = (typeof videoCourses)[number];
type Entry = {id:string; video:VideoCourse; lesson?:never} | {id:string; lesson:Lesson; video?:never};

export function topicPicture(topic:string) {
  if (topic === "二手交易") return "/course-posters/trade.webp";
  const id = ({
    "求职兼职":"job", "刷单返利":"rebate", "冒充客服":"customer",
    "交友与AI伪造":"face", "购票骗局":"ticket",
  } as Record<string,string>)[topic];
  return newsCases.find(c => c.id === id)?.poster ?? newsCases[0].poster;
}

function VideoCard({video}:{video:VideoCourse}) {
  return <a className="library-course" href={video.url} target="_blank" rel="noreferrer">
    <div className="library-cover">
      <img src={video.poster} alt={video.title+"原视频封面"} loading="lazy" referrerPolicy="no-referrer"/>
      <span>{video.format}<Play size={13}/></span>
    </div>
    <small>{video.topic}</small>
    <h3>{video.title}</h3>
    <p>{video.source} · 原站观看<ArrowUpRight size={14}/></p>
  </a>;
}

function TextCard({lesson,completed,onOpen}:{lesson:Lesson;completed:boolean;onOpen:(id:string)=>void}) {
  return <button className="library-course library-text-course" onClick={() => onOpen(lesson.id)}>
    <div className="library-cover">
      <img src={lessonArtwork(lesson.id)} alt={lessonEditorial[lesson.id].visualAlt} width={1200} height={800} loading="lazy"/>
      <span>图文微课<BookOpen size={13}/></span>
      {completed && <b><Check size={14}/>已读</b>}
    </div>
    <small>{lesson.topic}</small>
    <h3>{lesson.title}</h3>
    <p><span>图文 · 约 4 分钟</span><ArrowRight size={14}/></p>
  </button>;
}

export function LearningCatalog({progress,onOpen}:{progress:LearningProgress;onOpen:(id:string)=>void}) {
  const [format,setFormat] = useState("全部");
  const [subject,setSubject] = useState("全部课程");
  const [query,setQuery] = useState("");
  const [page,setPage]=useState(1);
  const heading=useRef<HTMLHeadingElement>(null);
  const match = (topic:string,title:string) =>
    (subject === "全部课程" || topic === subject) &&
    (!query.trim() || (title+topic).includes(query.trim()));
  const texts = lessons.filter(l => (format === "全部" || format === "图文课程") && match(l.topic??"",l.title));
  const videos = videoCourses.filter(v => (format === "全部" || format === v.format) && match(v.topic,v.title));
  const entries:Entry[] = [
    ...videos.map(video => ({id:video.id,video})),
    ...texts.map(lesson => ({id:lesson.id,lesson})),
  ];
  const order=format==="图文课程"?illustratedFeatured:featured;
  const priority = (id:string) => {const index=order.indexOf(id); return index < 0 ? order.length : index;};
  entries.sort((a,b) => priority(a.id)-priority(b.id));
  const totalPages=Math.ceil(entries.length/6),currentPage=Math.min(page,Math.max(1,totalPages));
  const visibleEntries=entries.slice((currentPage-1)*6,currentPage*6);
  function resetFilters() {setFormat("全部"); setSubject("全部课程"); setQuery("");setPage(1);}
  function turnPage(next:number){setPage(next);heading.current?.focus({preventScroll:true});window.scrollTo({top:0,behavior:"instant"});}
  const textOnly=format==="图文课程";
  const renderCourse=(entry:Entry)=>entry.video
    ? <VideoCard key={entry.id} video={entry.video}/>
    : <TextCard key={entry.id} lesson={entry.lesson} completed={progress.completed.includes(entry.id)} onOpen={onOpen}/>;
  return <section className="library-v2 library-editorial library-edition">
    <header className="library-heading">
      <div><h1 ref={heading} tabIndex={-1}>{textOnly?"图文微课":"学习中心"}</h1><p>{textOnly?"从一张信息，看懂一个骗局。":"认识套路，练习判断。"}</p></div>
      <label className="library-search"><Search size={18}/>
        <input aria-label="搜索课程" placeholder="搜索课程或关键词" value={query} onChange={e => {setQuery(e.target.value);setPage(1);}}/>
      </label>
    </header>
    <nav className="library-topics" aria-label="课程专题">
      {["全部课程",...subjects].map(s => <button key={s} aria-pressed={subject===s} onClick={() => {setSubject(s);setPage(1);}}>{s==="全部课程"?"全部":s}</button>)}
    </nav>
    <div className="library-layout">
      <div className="library-body">
        <nav className="format-nav" aria-label="教学形式">
          {formats.map(f => <button key={f} aria-pressed={format===f} onClick={() => {setFormat(f);setPage(1);}}>{f==="全部"?"全部形式":f}</button>)}
          <span className="library-result-count" aria-live="polite">{entries.length} 节课程</span>
        </nav>
        {visibleEntries.length>0&&<div className={`library-feature${visibleEntries.length===1?" library-feature--single":""}`}>
          {visibleEntries.slice(0,3).map(renderCourse)}
        </div>}
        {visibleEntries.length>3&&<section className="library-more" aria-label="更多课程">
          <div className="library-section"><h2>更多课程</h2><span>{subject==="全部课程"?"六个专题，按需学习。":subject}</span></div>
          <div className="library-grid">{visibleEntries.slice(3).map(renderCourse)}</div>
        </section>}
        {!entries.length && <div className="catalog-empty">
          <h3>没有找到对应课程</h3><p>试试其他教学形式或关键词。</p>
          <button onClick={resetFilters}>查看全部课程</button>
        </div>}
        {totalPages>1&&<nav className="library-pagination" aria-label="课程分页"><span>第 {currentPage} / {totalPages} 页</span><button disabled={currentPage===1} onClick={()=>turnPage(currentPage-1)} aria-label="上一页课程"><ArrowLeft size={15}/><span>上一页</span></button>{Array.from({length:totalPages},(_,i)=><button key={i} aria-label={`第${i+1}页课程`} aria-current={currentPage===i+1?"page":undefined} onClick={()=>turnPage(i+1)}>{i+1}</button>)}<button disabled={currentPage===totalPages} onClick={()=>turnPage(currentPage+1)} aria-label="下一页课程"><span>下一页</span><ArrowRight size={15}/></button></nav>}
        <p className="library-note">图文为原创教学微课，图片为教学示意，非真实案卷；真人与动画视频保留原始封面及出处，在来源网站观看。</p>
      </div>
    </div>
  </section>;
}

"use client";
import {useState} from "react";
import {ArrowRight,ArrowLeft,Search,Check} from "lucide-react";
import {lessons,quizItems,type LearningProgress} from "@/lib/learning";
import {knowledgeChunks} from "@/lib/knowledge";
import {subjects,topicPicture} from "./LearningCatalog";
export function QuestionBank({progress,onProgress,onAsk,initialScope=""}:{progress:LearningProgress;onProgress:(p:LearningProgress)=>void;onAsk:(q:string)=>void;initialScope?:string}){
 const [pool,setPool]=useState<typeof quizItems>(()=>quizItems.filter(q=>initialScope==="wrong"?q.id in progress.answers&&progress.answers[q.id]!==q.correct:initialScope!==""&&(initialScope==="all"||q.lesson===initialScope||lessons.find(l=>l.id===q.lesson)?.topic===initialScope))),[playing,setPlaying]=useState(Boolean(initialScope)),[index,setIndex]=useState(0),[choice,setChoice]=useState<number|null>(null),[submitted,setSubmitted]=useState(false),[results,setResults]=useState<Record<string,number>>({}),[kind,setKind]=useState("全部"),[query,setQuery]=useState("");
 const wrong=quizItems.filter(q=>q.id in progress.answers&&progress.answers[q.id]!==q.correct);
 function start(scope:string){let p=scope==="wrong"?wrong:quizItems.filter(q=>scope==="all"||q.lesson===scope||lessons.find(l=>l.id===q.lesson)?.topic===scope);p=p.filter(q=>kind==="全部"||(q.kind??"单选题")===kind);if(scope==="all"){p=p.slice();for(let i=p.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[p[i],p[j]]=[p[j],p[i]];}p=p.slice(0,10); }setPool(p);setPlaying(true);setIndex(0);setChoice(null);setSubmitted(false);setResults({});}
 const item=pool[index];
 const hasMatches=quizItems.some(q=>(kind==="全部"||(q.kind??"单选题")===kind)&&(!query||(q.question+q.explanation+(lessons.find(l=>l.id===q.lesson)?.topic??"")).includes(query)));
 if(playing)return <section className="bank-session"><button className="text-button" onClick={()=>setPlaying(false)}><ArrowLeft size={16}/>返回题库</button>{item?<div className="bank-workspace"><article className="learn-question"><div className="learn-question-meta"><span>{lessons.find(l=>l.id===item.lesson)?.topic} · {item.kind??"单选题"}</span><span>{index+1} / {pool.length}</span></div><h2>{item.question}</h2><fieldset disabled={submitted}><legend className="sr-only">请选择答案</legend>{item.options.map((o,i)=><label key={i} className={(choice===i?"is-chosen ":"")+(submitted&&i===item.correct?"is-correct":"")}><input type="radio" name={item.id} checked={choice===i} onChange={()=>setChoice(i)}/><span>{String.fromCharCode(65+i)}</span><span>{o}</span>{submitted&&i===item.correct&&<Check size={17}/>}</label>)}</fieldset>{submitted&&<div className="learn-explanation" role="status"><strong>{choice===item.correct?"判断正确":"看看漏掉了什么"}</strong><p>{item.explanation}</p><a href={knowledgeChunks.find(s=>s.id===item.sourceId)!.source.url} target="_blank" rel="noreferrer">查看资料依据</a><button onClick={()=>onAsk("请解释："+item.question)}>进一步了解</button></div>}<div className="learn-quiz-actions">{submitted?<button className="learn-primary" onClick={()=>{setIndex(index+1);setChoice(null);setSubmitted(false);}}>{index===pool.length-1?"查看练习小结":"下一题"}<ArrowRight size={16}/></button>:<button className="learn-primary" disabled={choice===null} onClick={()=>{if(choice!==null){onProgress({...progress,answers:{...progress.answers,[item.id]:choice}});setResults({...results,[item.id]:choice});setSubmitted(true);}}}>确认答案<ArrowRight size={16}/></button>}</div></article><aside className="bank-map"><h3>本轮进度</h3><progress value={Object.keys(results).length} max={pool.length}/><p>已答 {Object.keys(results).length} / {pool.length}</p><div>{pool.map((q,i)=><span key={q.id} aria-current={i===index?"step":undefined} className={q.id in results?(results[q.id]===q.correct?"right":"wrong"):""}>{i+1}</span>)}</div><p>提交后查看解析与依据。<br/>练习结果仅供学习参考。</p></aside></div>:<div className="bank-summary"><Check size={32}/><h2>{pool.length?"本轮练习完成":"当前范围没有待练题目"}</h2><p>本轮已答 {Object.keys(results).length} 题，答对 {pool.filter(q=>results[q.id]===q.correct).length} 题。</p><button className="learn-primary" onClick={()=>setPlaying(false)}>返回题库</button><button className="learn-outline" onClick={()=>start("wrong")}>重练错题</button></div>}</section>;
 return <section className="bank-home"><header className="library-heading"><div><h1>题库练习</h1><p>按专题、题型练习，答后查看解析与依据。</p></div><label className="library-search"><Search size={17}/><input aria-label="搜索题库专题" placeholder="搜索题目或知识点" value={query} onChange={e=>setQuery(e.target.value)}/></label></header><div className="bank-banner"><div><h2>综合练习</h2><p>识别线索 · 核实信息 · 选择行动</p><button onClick={()=>start("all")}>开始综合练习<ArrowRight size={19}/></button><small>每组最多10题，答后查看解析</small></div><img src="/design/question-desk.webp" alt="学习笔记与手机"/></div><div className="bank-layout"><aside className="bank-menu"><h2>练习方式</h2><button className="active" onClick={()=>setQuery("")}>专题练习</button><button onClick={()=>start("all")}>综合练习</button><button onClick={()=>start("wrong")}>错题重练 · {wrong.length}</button><h2>题型</h2>{["全部","单选题","判断题","材料题"].map(k=><button key={k} aria-pressed={kind===k} onClick={()=>setKind(k)}>{k}</button>)}</aside><div className="bank-topics"><div className="library-section"><h2>选择一个专题</h2><span>{quizItems.length} 道学习题</span></div><div className="bank-topic-grid">{subjects.map(s=>{const all=quizItems.filter(q=>lessons.find(l=>l.id===q.lesson)?.topic===s&&(kind==="全部"||(q.kind??"单选题")===kind));const qs=all.filter(q=>!query||(s+q.question+q.explanation).includes(query));return qs.length?<button key={s} onClick={()=>{setPool(qs);setPlaying(true);setIndex(0);setChoice(null);setSubmitted(false);setResults({});}}><img src={topicPicture(s)} alt="" loading="lazy" referrerPolicy="no-referrer"/><h3>{s}<ArrowRight size={19}/></h3><p>{qs.length} 题<span>已答 {qs.filter(q=>q.id in progress.answers).length}</span></p></button>:null;})}</div>{!hasMatches&&<p className="catalog-empty">没有匹配的内容，试试其他关键词。</p>}</div></div></section>;
}

"use client";
import {useState,useSyncExternalStore} from "react";
import {ArrowRight,BookOpen,Download,Trash2,History,Check} from "lucide-react";
import {lessons,quizItems,learningKey,readLearning,type LearningProgress} from "@/lib/learning";
import type {Session} from "@/lib/scenario";
const subscribeHydration=()=>()=>{};
function readProgress():LearningProgress{try{return readLearning(typeof window==="undefined"?null:JSON.parse(localStorage.getItem(learningKey)||"null"));}catch{return readLearning(null);}}
function recordDate(at:number|undefined,short=false){return at===undefined?"日期未记录":new Date(at).toLocaleDateString("zh-CN",short?{month:"long",day:"numeric"}:undefined);}
export function RecordWorkspace({session,previous,onOpen,onExport,onDelete}:{session:Session|null;previous:Session[];onOpen:()=>void;onExport:()=>void;onDelete:()=>void}){
 const [progress]=useState(readProgress);
 const loaded=useSyncExternalStore(subscribeHydration,()=>true,()=>false);
 if(!loaded)return <section className="record-workspace"><header className="record-heading"><div><h1>学习记录</h1></div></header><p className="module-loading" role="status">正在读取本地学习进度…</p></section>;
 const wrong=quizItems.filter(q=>q.id in progress.answers&&progress.answers[q.id]!==q.correct),nextLesson=lessons.find(l=>!progress.completed.includes(l.id))??lessons[0];
 return <section className="record-workspace"><header className="record-heading"><div><h1>学习记录</h1><p>回看课程、作答和情境练习。</p></div><span>保存在当前浏览器</span></header><div className="record-layout"><div className="record-journal"><div className="journal-title"><h2>练习与课程</h2>{session&&<button className="text-button" onClick={onExport}><Download size={16}/>导出记录</button>}</div>
